#include <map>
#include <string>

void rename_key(std::map<std::string, int>& m, 
                const std::string& old_key, 
                const std::string& new_key) {

    // 1. Check if old key exists and new key doesn't
    if (m.count(old_key) && !m.count(new_key)) {
        // 2. Copy the value to the new key (O(log N) insertion)
        m[new_key] = m[old_key];

        // 3. Erase the old key (O(log N) erasure)
        m.erase(old_key);
    }
}
